    public static class BenitoPérezGaldós
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Así como de la noche nace el claro del día, de la opresión nace la libertad.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Asusta pensar que las admiraciones más sinceras que tenemos son las de las personas que no nos han comprendido.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Como el agua a los campos, es necesaria la educación a nuestros secos y endurecidos entendimientos.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Contra paciencia, acción; contra miseria, bienestar.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "El amor es un arte que nunca se aprende y siempre se sabe.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "El dinero lo ganan todos aquellos que con paciencia y fina observación van detrás de los que lo pierden.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "El verdadero amor, el sólido y durable, nace del trato; lo demás es invención de los poetas, de los músicos y demás gente holgazana.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Esa polilla de la voluntad que llamamos lástima.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Eso es hoy el agricultor castellano: santo condenado y guerrero sin gloria.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "La experiencia es una llama que no alumbra sino quemando.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "No puede sostenerse en las acciones de la vida el criterio pesimista, que suele ser el disimulo del egoísmo.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Yo no tengo la culpa de que la vida se nutra de la virtud y del pecado, de lo hermoso y de lo feo.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Amenguada considerablemente mi vista, he perdido en absoluto el don de la literatura. Con profunda tristeza puedo asegurar que la letra de molde ha huido de mí, como un mundo que se desvanece en las tinieblas.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "A pesar de toda mi labor pasada, si en el presente quiero vivir no tengo más remedio que dictar todas las mañanas durante cuatro o cinco horas y estrujarme el cerebro hasta que dé el último paso en esta vida.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Creo que la literatura debe ser enseñanza, ejemplo. Yo escribí siempre, excepto en algunos momentos de lirismo, con el propósito de marcar huella.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Desconfiemos siempre de las ideas de fácil adaptación al criterio vulgar; desconfiemos del amaneramiento de la opinión, que no es más que un remedio contra la incomodidad de pensar por cuenta propia.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Imagen de la vida es la Novela, y el arte de componerla estriba en reproducir los caracteres humanos, las pasiones, las debilidades, lo grande y lo pequeño, las almas y las fisonomías, todo lo espiritual y lo físico que nos constituye y nos rodea, y el lenguaje, que es la marca de raza, y las viviendas, que son el signo de familia, y la vestidura, que diseña los últimos trazos externos de la personalidad: todo esto sin olvidar que debe existir perfecto fiel de balanza entre la exactitud y la belleza de la reproducción...", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Si alguna calidad posee el que esto escribe, digna de la estimulación de sus amigos, es la de vivir con el oído atento al murmullo social, distrayéndose poco de ese trabajo de vigía o de escucha: trabajo que subyuga el espíritu, se convierte en pasión y acaba por ser oficio.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Una de las mayores dificultades con que tropieza la novela en España consiste en lo poco hecho y trabajado que está el lenguaje literario para asimilarse los matices de la conversación corriente.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "Un hombre tonto no es capaz de hacen en ningún momento de su vida los disparates que hacen a veces las naciones, dirigidas por centenares de hombres de talento.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "El agua ya no quiere ser agua, y es cristal resbaladizo: el aire no quiere ser aire, y es navaja de afeitar: el fuego no calienta, ni derrite, ni quema.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "El vil metal es causa de todos los conflictos: todas las crisis políticas son juegos de chicos, comparadas con una crisis financiera.", Author = "Benito Pérez Galdós" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Benito_Pérez_Galdós", Text = "No es la Discordia, es la crisis. La crisis financiera, que es la más terrible de las crisis. La pobreza, mas no de uno, sino de todos los españoles, la bancarrota de una nación, la sublimidad del desfalco, el trueno reducido a su más augusta expresión.", Author = "Benito Pérez Galdós" },
        };
    }
